    {
        var sensor = new TemperatureSensor();
        var display = new TemperatureDisplay();

        display.Subscribe(sensor);

        for (int i = 0; i < 5; i++)
        {
            sensor.SimulateReading();
        }

        display.Unsubscribe();

        Console.ReadLine();
    }
    }
