                new Person { Name = "Bob", Age = 20 },
                new Person { Name = "Charlie", Age = 35 }
            };

            PersonNameComparer comparer = new PersonNameComparer();

            var sortedPeople = people.OrderBy(p => p, comparer).ToList();

