        Person person3 = new Person { Name = "Jane Doe", Age = 30 };

        Console.WriteLine($"person1 and person2 are equal: {person1.Equals(person2)}");
        Console.WriteLine($"person1 and person3 are equal: {person1.Equals(person3)}");
    }
