        };

        Console.WriteLine("Before sorting:");
        foreach (var person in people)
            Console.WriteLine($"{person.Name} ({person.Age})");

        // Sort the list using the IComparable implementation
        people.Sort();

        Console.WriteLine("\nAfter sorting:");
        foreach (var person in people)
            Console.WriteLine($"{person.Name} ({person.Age})");
    }
}
