    public int Age { get; set; }

    public Person(string name, int age)
    {
        Name = name;
        Age = age;
    }

    public bool Equals(Person other)
    {
        if (other == null) return false;
        if (Name == other.Name && Age == other.Age)
            return true;
        return false;
    }

