using System;
using System.Runtime.Serialization;

[Serializable]
public class Person : ICloneable
{
    public string Name { get; set; }
    public int Age { get; set; }

    public Person(string name, int age)
    {
        Name = name;
        Age = age;
    }

    // ICloneable implementation
