        Console.WriteLine($"Name: {person,10}"); // Custom format N, alignment 10
        Console.WriteLine($"Age: {person,5}"); // Custom format A, alignment 5
        Console.WriteLine($"Full Name and Age: {person,20}"); // Custom format B, alignment 20
