{
    public int Compare(Person x, Person y)
    {
        int lastNameComparison = string.Compare(x.LastName, y.LastName);

        if (lastNameComparison != 0) return lastNameComparison;

        return string.Compare(x.FirstName, y.FirstName);
    }
}

// Define Main method
