        Person person2 = new Person("John", 30);
        Person person3 = new Person("Jane", 30);

        Console.WriteLine($"person1.Equals(person2): {person1.Equals(person2)}");
        Console.WriteLine($"person1.Equals(person3): {person1.Equals(person3)}");
    }
    }
