            Person p2 = new Person("John", 30);
            Person p3 = new Person("Jane", 25);

            Console.WriteLine("p1 == p2: " + p1.Equals(p2)); // True
            Console.WriteLine("p1 == p3: " + p1.Equals(p3)); // False
        }
    }
    }
