        // Modify the clone
        person2.Name = "Jane";
        person2.Age = 25;

        // Output the results
        Console.WriteLine("Original person: " + person1.Name + ", " + person1.Age);
        Console.WriteLine("Cloned person: " + person2.Name + ", " + person2.Age);
    }
    }
